17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.time.LocalDate;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.Optional;
24	import java.util.UUID;
25	
26	import org.slf4j.Logger;
27	import org.slf4j.LoggerFactory;
28	import org.springframework.http.HttpHeaders;
29	import org.springframework.http.HttpStatus;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.mapper.OwnerMapper;
32	import org.springframework.samples.petclinic.mapper.PetMapper;
33	import org.springframework.samples.petclinic.mapper.VisitMapper;
34	import org.springframework.samples.petclinic.model.Owner;
35	import org.springframework.samples.petclinic.model.Pet;
36	import org.springframework.samples.petclinic.model.Visit;
37	import org.springframework.samples.petclinic.rest.api.OwnersApi;
38	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
39	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.PetDto;
41	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
44	import org.springframework.samples.petclinic.service.ClinicService;
45	import org.springframework.security.access.prepost.PreAuthorize;
46	import org.springframework.web.bind.annotation.CrossOrigin;
47	import org.springframework.web.bind.annotation.RequestMapping;
48	import org.springframework.web.bind.annotation.RestController;
49	import org.springframework.web.util.UriComponentsBuilder;
50	
51	import jakarta.transaction.Transactional;
52	
53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
63	
64	    private final ClinicService clinicService;
65	
66	    private final OwnerMapper ownerMapper;
67	
68	    private final PetMapper petMapper;
69	
70	    private final VisitMapper visitMapper;
71	
72	    public OwnerRestControllerV1(ClinicService clinicService,
73	                                 OwnerMapper ownerMapper,
74	                                 PetMapper petMapper,
75	                                 VisitMapper visitMapper) {
76	        this.clinicService = clinicService;
77	        this.ownerMapper = ownerMapper;
78	        this.petMapper = petMapper;
79	        this.visitMapper = visitMapper;
80	    }
81	
82	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
83	    @Override
84	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
85	        Collection<Owner> owners;
86	        if (lastName != null) {
87	            owners = this.clinicService.findOwnerByLastName(lastName);
88	        } else {
89	            owners = this.clinicService.findAllOwners();
90	        }
91	        if (owners.isEmpty()) {
92	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
93	        }
94	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
95	    }
96	
97	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
98	    @Override
99	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
100	        Owner owner = this.clinicService.findOwnerById(ownerId);
101	        if (owner == null) {
102	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
103	        }
104	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
110	        HttpHeaders headers = new HttpHeaders();
111	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
112	        if (!normalizeNewOwner(owner)) {
113	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
114	        }
115	        if (dailyLimitReached(owner.getRegistrationDate())) {
116	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
117	        }
118	        if (cityIsAtCapacity(owner.getCity())) {
119	            return new ResponseEntity<>(HttpStatus.CONFLICT);
120	        }
121	        Optional<Owner> householdMember = findHouseholdMember(owner);
122	        if (householdMember.isPresent() && Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
123	            joinHousehold(owner, householdMember.get());
124	        }
125	        if (identityKeyAlreadyUsed(owner)) {
126	            return new ResponseEntity<>(HttpStatus.CONFLICT);
127	        }
128	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
129	        owner.setNamesakeCount(countNamesakes(owner));
130	        owner.setMembershipNumber(membershipNumber(owner));
131	        owner.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
132	        owner.setHouseholdSize(householdSize(owner));
133	        this.clinicService.saveOwner(owner);
134	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
135	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
136	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
137	        headers.setLocation(UriComponentsBuilder.newInstance()
138	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
139	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
140	    }
141	
142	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
143	    @Override
144	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
145	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
146	        if (currentOwner == null) {
147	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
148	        }
149	        currentOwner.setAddress(ownerFieldsDto.getAddress());
150	        currentOwner.setCity(ownerFieldsDto.getCity());
151	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
152	        currentOwner.setLastName(ownerFieldsDto.getLastName());
153	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
154	        String email = ownerFieldsDto.getEmail();
155	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
156	        this.clinicService.saveOwner(currentOwner);
157	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
158	    }
159	
160	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
161	    @Transactional
162	    @Override
163	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
164	        Owner owner = this.clinicService.findOwnerById(ownerId);
165	        if (owner == null) {
166	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
167	        }
168	        this.clinicService.deleteOwner(owner);
169	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
170	    }
171	
172	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
173	    @Override
174	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
175	        Owner owner = this.clinicService.findOwnerById(ownerId);
176	        if (owner == null) {
177	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
178	        }
179	        HttpHeaders headers = new HttpHeaders();
180	        Pet pet = petMapper.toPet(petFieldsDto);
181	        owner.setId(ownerId);
182	        pet.setOwner(owner);
183	        pet.getType().setName(null);
184	        this.clinicService.savePet(pet);
185	        PetDto petDto = petMapper.toPetDto(pet);
186	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
187	            .buildAndExpand(pet.getId()).toUri());
188	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
189	    }
190	
191	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
192	    @Override
193	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
194	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
195	        if (currentOwner != null) {
196	            Pet currentPet = this.clinicService.findPetById(petId);
197	            if (currentPet != null) {
198	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
199	                currentPet.setName(petFieldsDto.getName());
200	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
201	                this.clinicService.savePet(currentPet);
202	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
203	            }
204	        }
205	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
206	    }
207	
208	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
209	    @Override
210	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
211	        HttpHeaders headers = new HttpHeaders();
212	        Visit visit = visitMapper.toVisit(visitFieldsDto);
213	        Pet pet = new Pet();
214	        pet.setId(petId);
215	        visit.setPet(pet);
216	        this.clinicService.saveVisit(visit);
217	        VisitDto visitDto = visitMapper.toVisitDto(visit);
218	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
219	            .buildAndExpand(visit.getId()).toUri());
220	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
221	    }
222	
223	
224	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
225	    @Override
226	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
227	        Owner owner = this.clinicService.findOwnerById(ownerId);
228	        if (owner != null) {
229	            Pet pet = owner.getPet(petId);
230	            if (pet != null) {
231	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
232	            }
233	        }
234	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
235	    }
236	
237	    /**
238	     * Normalise the incoming fields of a freshly-mapped owner in place, applying
239	     * the canonical form each stored value must take: the address is trimmed,
240	     * whitespace-collapsed, upper-cased and its common abbreviations expanded, the
241	     * telephone is converted to E.164, any email is lower-cased and a missing
242	     * registration date defaults to today. Field-level rejections are reported here
243	     * rather than inline in {@link #addOwner}, and normalisation runs before any
244	     * household comparison so those comparisons see the canonical values.
245	     *
246	     * @param owner the freshly-mapped owner to normalise
247	     * @return {@code true} if the fields are valid, or {@code false} if the address
248	     *         is blank after normalisation or the telephone cannot form a valid
249	     *         E.164 number, in which case the request must be rejected with
250	     *         {@code 400 Bad Request}
251	     */
252	    private boolean normalizeNewOwner(Owner owner) {
253	        String address = Owner.normalizeAddress(owner.getAddress());
254	        if (address.isEmpty()) {
255	            return false;
256	        }
257	        owner.setAddress(address);
258	        String telephone = toE164(owner.getTelephone());
259	        if (telephone == null) {
260	            return false;
261	        }
262	        owner.setTelephone(telephone);
263	        if (owner.getEmail() != null) {
264	            owner.setEmail(owner.getEmail().toLowerCase());
265	        }
266	        if (owner.getRegistrationDate() == null) {
267	            owner.setRegistrationDate(LocalDate.now());
268	        }
269	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
270	        return true;
271	    }
272	
273	    /**
274	     * Roll the given date forward to the next business day when it falls on a
275	     * weekend: a Saturday or Sunday is advanced to the following Monday, while a
276	     * weekday is returned unchanged. Applied to the effective registration date
277	     * (whether supplied in the request or defaulted to the server date) so that
278	     * every value derived from it uses the adjusted business day.
279	     *
280	     * @param date the effective registration date
281	     * @return the same date if it is a weekday, otherwise the next Monday
282	     */
283	    private static LocalDate rollToBusinessDay(LocalDate date) {
284	        switch (date.getDayOfWeek()) {
285	            case SATURDAY:
286	                return date.plusDays(2);
287	            case SUNDAY:
288	                return date.plusDays(1);
289	            default:
290	                return date;
291	        }
292	    }
293	
294	    /**
295	     * Determine whether the candidate owner's identity key collides with any existing
296	     * owner's. This is the single, consolidated duplicate check: it subsumes the
297	     * former separate telephone, email and household checks by comparing the whole
298	     * derived {@code identityKey} ({@code normalizedTelephone + '|' + (email or empty)
299	     * + '|' + householdId}). Only an exact full-key match is a duplicate, so two owners
300	     * that agree on some — but not all — of the key's parts (for example two members of
301	     * the same household with different telephones) are not duplicates. Evaluated after
302	     * normalisation and household resolution, so the candidate's key reflects its
303	     * canonical field values and any household it has joined.
304	     *
305	     * @param owner the candidate owner being created, after household resolution
306	     * @return {@code true} if an existing owner has the same identity key
307	     */
308	    private boolean identityKeyAlreadyUsed(Owner owner) {
309	        String identityKey = owner.getIdentityKey();
310	        return this.clinicService.findAllOwners().stream()
311	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
312	    }
313	
314	    /**
315	     * Find an existing owner that belongs to the same household as the given owner,
316	     * i.e. shares the same last name and address (compared case-insensitively with
317	     * runs of whitespace collapsed to a single space).
318	     *
319	     * @param owner the candidate owner being created
320	     * @return the matching existing owner, or empty if none exists
321	     */
322	    private Optional<Owner> findHouseholdMember(Owner owner) {
323	        return this.clinicService.findAllOwners().stream()
324	            .filter(existing -> existing.sameHouseholdAs(owner))
325	            .findFirst();
326	    }
327	
328	    /**
329	     * Assign the joining owner and an existing household member the same stable
330	     * household identifier. The identifier is derived deterministically from the
331	     * shared household key (last name + address, normalised), so every owner in a
332	     * household resolves to the same value; the existing member is updated when it
333	     * does not already carry it.
334	     *
335	     * @param owner    the owner being created
336	     * @param existing an existing owner in the same household
337	     */
338	    private void joinHousehold(Owner owner, Owner existing) {
339	        String householdId = UUID
340	            .nameUUIDFromBytes(owner.householdKey().getBytes(StandardCharsets.UTF_8)).toString();
341	        owner.setHouseholdId(householdId);
342	        if (!householdId.equals(existing.getHouseholdId())) {
343	            existing.setHouseholdId(householdId);
344	            this.clinicService.saveOwner(existing);
345	        }
346	    }
347	
348	    /**
349	     * Count how many owners belong to the given owner's household once this create
350	     * completes: the owners that already share its {@code householdId} plus the owner
351	     * being created. Evaluated after any {@link #joinHousehold(Owner, Owner)} has run,
352	     * so the household identifier (and any existing member updated to it) is already in
353	     * place. An owner that has not joined a household (no {@code householdId}) is a
354	     * household of one.
355	     *
356	     * @param owner the candidate owner being created, after household resolution
357	     * @return the household member count after this create (at least {@code 1})
358	     */
359	    private int householdSize(Owner owner) {
360	        String householdId = owner.getHouseholdId();
361	        if (householdId == null) {
362	            return 1;
363	        }
364	        long existing = this.clinicService.findAllOwners().stream()
365	            .filter(other -> householdId.equals(other.getHouseholdId()))
366	            .count();
367	        return (int) existing + 1;
368	    }
369	
370	    /**
371	     * Count the existing owners that share the given owner's first and last name,
372	     * compared case-insensitively (surrounding whitespace trimmed). Evaluated
373	     * before the new owner is saved, so the result reflects only owners that
374	     * already existed at creation time.
375	     *
376	     * @param owner the candidate owner being created
377	     * @return the number of existing namesakes
378	     */
379	    private int countNamesakes(Owner owner) {
380	        String firstName = normalizeName(owner.getFirstName());
381	        String lastName = normalizeName(owner.getLastName());
382	        return (int) this.clinicService.findAllOwners().stream()
383	            .filter(existing -> normalizeName(existing.getFirstName()).equals(firstName)
384	                && normalizeName(existing.getLastName()).equals(lastName))
385	            .count();
386	    }
387	
388	    private static String normalizeName(String value) {
389	        return value == null ? "" : value.trim().toLowerCase();
390	    }
391	
392	    /**
393	     * Build the next customer code, formatted {@code <CITY3>-<LAST3>-<NNNN>}: CITY3
394	     * is the upper-cased first three letters of the given city, LAST3 the upper-cased
395	     * first three letters of the given last name and NNNN a per-city 4-digit
396	     * zero-padded sequence equal to one more than the number of owners already in
397	     * that city (e.g. {@code SYD-SMI-0007}).
398	     *
399	     * @param city     the owner's city
400	     * @param lastName the owner's last name
401	     * @return the assigned customer code
402	     */
403	    /**
404	     * Determine whether the given city has already reached its owner capacity, i.e.
405	     * it already contains 50 or more existing owners (compared case-insensitively
406	     * with surrounding whitespace trimmed). A new owner may not be created in a city
407	     * that is at capacity.
408	     *
409	     * @param city the candidate owner's city
410	     * @return {@code true} if the city already holds 50 or more owners
411	     */
412	    private boolean cityIsAtCapacity(String city) {
413	        String normalizedCity = normalizeName(city);
414	        long count = this.clinicService.findAllOwners().stream()
415	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizedCity))
416	            .count();
417	        return count >= 50;
418	    }
419	
420	    /**
421	     * Determine whether the daily owner-creation limit has already been reached, i.e.
422	     * 100 or more owners already carry the given registration date. A new owner may
423	     * not be created once that day's cap is reached.
424	     *
425	     * @param registrationDate the registration date the new owner would be created with
426	     * @return {@code true} if 100 or more existing owners share that registration date
427	     */
428	    private boolean dailyLimitReached(LocalDate registrationDate) {
429	        long count = this.clinicService.findAllOwners().stream()
430	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
431	            .count();
432	        return count >= 100;
433	    }
434	
435	    /**
436	     * Determine whether more than 80 owners have already been created for the given
437	     * registration date, i.e. strictly more than 80 existing owners carry that date.
438	     * Evaluated before the new owner is saved, so it reflects only owners that
439	     * already existed at creation time.
440	     *
441	     * @param registrationDate the registration date the new owner would be created with
442	     * @return {@code true} if more than 80 existing owners share that registration date
443	     */
444	    private boolean bulkSignupWarning(LocalDate registrationDate) {
445	        long count = this.clinicService.findAllOwners().stream()
446	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
447	            .count();
448	        return count > 80;
449	    }
450	
451	    private String nextCustomerCode(String city, String lastName) {
452	        String city3 = prefix3(city);
453	        String last3 = prefix3(lastName);
454	        long sequence = this.clinicService.findAllOwners().stream()
455	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizeName(city)))
456	            .count() + 1L;
457	        return String.format("%s-%s-%04d", city3, last3, sequence);
458	    }
459	
460	    private static String prefix3(String value) {
461	        String v = value == null ? "" : value;
462	        return v.substring(0, Math.min(3, v.length())).toUpperCase();
463	    }
464	
465	    /**
466	     * Build the owner's membership number, formatted {@code <customerCode>-M<YY>}
467	     * where {@code <customerCode>} is the owner's already-assigned customer code and
468	     * YY is the last two digits of the registration date's year (e.g.
469	     * {@code SMI-0007-M26}). Evaluated after the customer code and registration date
470	     * have been set.
471	     *
472	     * @param owner the owner being created, with customer code and registration date
473	     *              already assigned
474	     * @return the assigned membership number
475	     */
476	    private String membershipNumber(Owner owner) {
477	        int yy = owner.getRegistrationDate().getYear() % 100;
478	        return String.format("%s-M%02d", owner.getCustomerCode(), yy);
479	    }
480	
481	    /**
482	     * Normalise a telephone number to E.164 form: keep a leading '+' and country
483	     * code when present, otherwise assume country code '+61' and drop a single
484	     * leading '0' from the national digits. Spaces, dashes and brackets are
485	     * stripped. The result must contain 8 to 15 digits after the '+'.
486	     *
487	     * <p>In addition, the national-number length is validated against the country
488	     * code: a {@code +61} (Australia) number must have exactly 9 national digits
489	     * and a {@code +1} (NANP) number must have exactly 10 national digits. A number
490	     * whose national-number length is wrong for its country code is rejected.
491	     *
492	     * @return the E.164 string (e.g. "+61412345678"), or {@code null} if the
493	     *         input cannot form a valid E.164 number.
494	     */
495	    private static String toE164(String raw) {
496	        if (raw == null) {
497	            return null;
498	        }
499	        String cleaned = raw.replaceAll("[\\s()-]", "");
500	        String digits;
501	        if (cleaned.startsWith("+")) {
502	            digits = cleaned.substring(1);
503	        } else {
504	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
505	            digits = "61" + national;
506	        }
507	        if (!digits.matches("\\d{8,15}")) {
508	            return null;
509	        }
510	        if (!nationalNumberLengthValid(digits)) {
511	            return null;
512	        }
513	        return "+" + digits;
514	    }
515	
516	    /**
517	     * Validate the length of the national number (the digits after the country
518	     * code) against the country code carried by the given E.164 digit string: a
519	     * {@code 61} (Australia) number requires exactly 9 national digits and a
520	     * {@code 1} (NANP) number requires exactly 10 national digits. Country codes
521	     * without a pinned length are accepted (only the generic 8-15 digit rule
522	     * applies to them).
523	     *
524	     * @param digits the E.164 digits without the leading '+'
525	     * @return {@code true} if the national-number length is correct for the country
526	     */
527	    private static boolean nationalNumberLengthValid(String digits) {
528	        if (digits.startsWith("61")) {
529	            return digits.length() - 2 == 9;
530	        }
531	        if (digits.startsWith("1")) {
532	            return digits.length() - 1 == 10;
533	        }
534	        return true;
535	    }
536	}
